import puppeteer from 'puppeteer-core';
import fs from 'fs';

const candidates=['/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'];
const executablePath=candidates.find(p=>fs.existsSync(p));
if(!executablePath)throw new Error('No Chrome executable found');
const browser=await puppeteer.launch({headless:true,executablePath,args:['--no-sandbox','--disable-setuid-sandbox']});
const page=await browser.newPage();
await page.setViewport({width:390,height:844,isMobile:true,hasTouch:true,deviceScaleFactor:3});
await page.setUserAgent('Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1');
const consoleErrors=[];const pageErrors=[];
page.on('console',msg=>{if(msg.type()==='error')consoleErrors.push(msg.text())});
page.on('pageerror',err=>pageErrors.push(String(err)));
await page.goto('https://almohammdin.github.io/majalis/?admin-mobile-test=1',{waitUntil:'networkidle2',timeout:60000});
await page.waitForSelector('#adminAccessButton',{timeout:15000});
const before=await page.$eval('#adminLoginModal',el=>({hidden:el.hidden,display:getComputedStyle(el).display}));
await page.click('#adminAccessButton');
await new Promise(r=>setTimeout(r,500));
const after=await page.$eval('#adminLoginModal',el=>({hidden:el.hidden,display:getComputedStyle(el).display}));
console.log('MODAL_BEFORE',JSON.stringify(before));
console.log('MODAL_AFTER',JSON.stringify(after));
if(after.hidden||after.display==='none')throw new Error('Admin login modal did not open');
await page.type('#adminEmail','mobile-test@example.com');
await page.type('#adminPassword','wrong-password-123');
await page.click('#adminLoginSubmit');
await new Promise(r=>setTimeout(r,3500));
const result=await page.evaluate(()=>({message:document.getElementById('adminLoginMessage')?.textContent||'',disabled:document.getElementById('adminLoginSubmit')?.disabled||false,modalHidden:document.getElementById('adminLoginModal')?.hidden||false}));
console.log('LOGIN_RESULT',JSON.stringify(result));
console.log('PAGE_ERRORS',JSON.stringify(pageErrors));
console.log('CONSOLE_ERRORS',JSON.stringify(consoleErrors.slice(-20)));
if(!result.message.trim()&&result.disabled)throw new Error('Login submit became stuck without feedback');
if(!result.message.trim())throw new Error('Login submit produced no user feedback');
await browser.close();
